Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"
$repo = "C:\SIRAJ\Repositories\spot-speculation-bot"
Set-Location $repo

Write-Host "============================================================================================================================"
Write-Host "AKAH BOT - REV262 SYNC + P38 2023 REPLICATION RETRY V1R11 STAGING-CLOSURE FIX"
Write-Host "============================================================================================================================"
Write-Host "PREVIOUS_V1R10_SCIENCE=COMPLETED_BEFORE_STAGING_FAILURE"
Write-Host "PREVIOUS_V1R10_CLASSIFICATION=TEMPORAL_REPLICATION_NOT_SUPPORTED_PRIMARY_DELTA_NONPOSITIVE_CLOSE_CANDIDATE"
Write-Host "PREVIOUS_V1R10_FAILURE=IGNORED_LOG_REJECTED_BY_GIT_ADD"
Write-Host "REV262_SYNC_REQUIRED=YES"
Write-Host "SCIENTIFIC_REPLAY_CHANGE=NO"
Write-Host "P36_FROZEN_GATES_CHANGE=NO"
Write-Host "SOURCE_AUTHORITY_CHANGE=NO"
Write-Host "PAIR_SET_CHANGE=NO"
Write-Host "RESULT_BINDING_CHANGE=NO"
Write-Host "ONLY_FIX=IGNORED_AWARE_EXACT_SCOPE_STAGING"
Write-Host "IGNORED_ARTIFACT_POLICY=FORCE_ADD_EXACT_PATH_ONLY"
Write-Host "STAGE_SCOPE_VERIFICATION=EXACT"
Write-Host "SEARCH_OR_TUNING=NO"
Write-Host "2024_ACCESS=NO"
Write-Host "2025_ACCESS=NO"
Write-Host "PRODUCTION_CHANGE=NO"

$tmpRoot = Join-Path $env:TEMP ("akah_p38_v1r11_" + [guid]::NewGuid().ToString("N"))
New-Item -ItemType Directory -Path $tmpRoot -Force | Out-Null
$syncFile = Join-Path $tmpRoot "sync_rev262.ps1"
$p38File = Join-Path $tmpRoot "p38_v1r11.py"

try {
    [IO.File]::WriteAllBytes($syncFile, [Convert]::FromBase64String(""))
    [IO.File]::WriteAllBytes($p38File, [Convert]::FromBase64String(""))

    & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $syncFile
    if ($LASTEXITCODE -ne 0) { throw "REV262_SYNC_FAILED" }

    & git.exe fetch origin "+refs/heads/governance/akah-system-charter-live:refs/remotes/origin/governance/akah-system-charter-live"
    if ($LASTEXITCODE -ne 0) { throw "REV262_REMOTE_FETCH_VERIFY_FAILED" }

    $remoteCommit = (& git.exe rev-parse refs/remotes/origin/governance/akah-system-charter-live).Trim()
    $manifestText = (& git.exe show "refs/remotes/origin/governance/akah-system-charter-live:governance/AKAH_BOT_SYSTEM_CHARTER_GITHUB_SYNC_MANIFEST.json" | Out-String)
    if ($LASTEXITCODE -ne 0 -or -not $manifestText) { throw "REV262_REMOTE_MANIFEST_READ_FAILED" }
    $manifest = $manifestText | ConvertFrom-Json

    if ([int]$manifest.charter_revision -ne 262) {
        throw "REV262_REMOTE_MANIFEST_REVISION_MISMATCH=$($manifest.charter_revision)"
    }
    if ([string]$manifest.source_head -ne "3522a14176b275f1fe411e744a2739ca1aef10bb") {
        throw "REV262_REMOTE_MANIFEST_SOURCE_HEAD_MISMATCH=$($manifest.source_head)"
    }
    if ([string]$manifest.latest_completed_task.task_id -ne "FINAL_EXIT_BRAIN_PRE_2024_ARCHITECTURE_P38_TRANSITION_ADMISSION_ONLY_2023_TEMPORAL_REPLICATION_EXECUTION_V1_RETRY_V1_RETRY_V1_RETRY_V1") {
        throw "REV262_REMOTE_MANIFEST_LATEST_TASK_MISMATCH=$($manifest.latest_completed_task.task_id)"
    }
    if ([string]$manifest.latest_completed_task.outcome -ne "FAIL_CLOSED") {
        throw "REV262_REMOTE_MANIFEST_OUTCOME_MISMATCH=$($manifest.latest_completed_task.outcome)"
    }
    if ([string]$manifest.current_bottleneck -ne "FINAL_EXIT_BRAIN_PRE_2024_ARCHITECTURE_P38_TRANSITION_ADMISSION_ONLY_2023_TEMPORAL_REPLICATION_EXECUTION_V1_RETRY_V1_RETRY_V1_RETRY_V1_RETRY_V1") {
        throw "REV262_REMOTE_MANIFEST_BOTTLENECK_MISMATCH=$($manifest.current_bottleneck)"
    }

    Write-Host "REV262_REMOTE_VERIFICATION=PASS"
    Write-Host "REV262_REMOTE_COMMIT=$remoteCommit"

    $env:AKAH_GITHUB_SYNC_COMMIT = $remoteCommit
    $python = Join-Path $repo ".venv\Scripts\python.exe"

    & $python -m py_compile $p38File
    if ($LASTEXITCODE -ne 0) { throw "P38_V1R11_EMBEDDED_PY_COMPILE_FAIL" }
    Write-Host "P38_V1R11_EMBEDDED_PY_COMPILE=PASS"

    & $python $p38File
    if ($LASTEXITCODE -ne 0) { throw "P38_V1R11_EXECUTION_FAILED_PRE_BEGIN_OR_GOVERNANCE" }
}
finally {
    Remove-Item -LiteralPath $tmpRoot -Recurse -Force -ErrorAction SilentlyContinue
}
